shell_commands:
node -e "
import {readFileSync, readdirSync} from 'node:fs';
import {createRequire} from 'node:module';
const req = createRequire(import.meta.url);
const pkgPath = req.resolve('@re-cinq/eslint-plugin-re-lint');
console.log('pkgPath:', pkgPath);
for (const name of ['require-spec-link', 'require-colocated-tests', 'test-imports-its-subject', 'max-expects', 'no-nondeterministic-tests', 'require-status-matches-coverage']) {
  const p = pkgPath.replace(/index\.js$/, 'rules/' + name + '.js');
  try {
    console.log('=== ' + name + ' ===');
    console.log(readFileSync(p, 'utf8'));
  } catch (e) {
    console.log('err', name, e.message);
  }
}
"

node -e "
import {readFileSync} from 'node:fs';
const base = 'node_modules/@re-cinq/eslint-plugin-re-lint/dist/rules/';
for (const name of ['require-spec-link', 'require-colocated-tests', 'test-imports-its-subject', 'max-expects', 'no-nondeterministic-tests', 'require-status-matches-coverage', 'no-vague-names', 'no-negative-names']) {
  console.log('=== ' + name + ' ===');
  console.log(readFileSync(base + name + '.mjs', 'utf8'));
}
"
